#nullable enable

using Alba;
using Drafting.Contracts;
using Drafting.Slices.Drafting;
using Microsoft.Extensions.DependencyInjection;
using Shouldly;
using Wolverine;
using Xunit;
using Xunit.Abstractions;

namespace Drafting.IntegrationTests.Concurrency;

/// <summary>
/// THE TWO ARMS OF THIS SLICE ARE NOT EQUIVALENT UNDER CONTENTION, AND THAT IS THE POINT OF THIS FILE.
///
/// <c>revise-subject</c> is implemented twice against one model — <see cref="ReviseSubjectEndpoint"/> over
/// Wolverine.HTTP, and <see cref="ReviseSubjectHandler"/> as a message. Identical middleware
/// (<c>[WriteAggregate]</c> fetches, folds, version-checks and saves), identical decider shape, identical
/// rules. The README used to present them as a free choice of transport.
///
/// **They differ on exactly one thing, and it is invisible until two callers collide.** Program.cs carries
///
///     opts.OnException&lt;ConcurrencyException&gt;().RetryTimes(3);
///     opts.OnException&lt;EventStreamUnexpectedMaxEventIdException&gt;().RetryTimes(3);
///
/// and those are MESSAGE-pipeline policies. A Wolverine.HTTP endpoint is not a message and never enters
/// that pipeline, so the collision is never retried and leaves as a 500 instead of the ordinary business
/// refusal the kit promises.
///
/// WHY THE OBVIOUS EVIDENCE IS WORTHLESS, recorded because it nearly shipped as the justification: it is
/// tempting to argue from the generated code having no try/catch. Dump every generated file with
/// <c>codegen write</c> and NONE of them has one — message handlers included. Wolverine's retry lives in
/// the executor AROUND the generated method, so its absence there is expected either way and proves
/// nothing. Only the behaviour distinguishes them, which is why this is a test and not a paragraph.
///
/// THE FIX, when a slice needs the retry: keep the decider as a message handler and make the endpoint a
/// five-line adapter that calls <c>bus.InvokeAsync</c>. Same route, same body, same status codes — the wire
/// does not change. Costs one in-process hop.
///
/// AND DO NOT INSTEAD TRANSLATE THE COLLISION with Wolverine.HTTP's <c>OnException</c> convention. A version
/// conflict does not mean the business rule failed; it means somebody else appended to this stream. On a
/// stream shared between contexts that somebody may be an unrelated slice, and the translation would refuse
/// a perfectly valid command with a rule name that is untrue. A retry re-reads; a translation guesses.
/// </summary>
public sealed class RetryReachesTheMessageArmOnlyTests(AppFixture fixture, ITestOutputHelper output)
    : IntegrationContext(fixture)
{
    // Two callers that have BOTH read before either commits. Releasing them with a gate is what makes this
    // a race rather than two sequential requests the database happens to order — see ANTI-PATTERNS #14 and
    // probes/concurrency-invariant.cs, where Task.WhenAll alone reported a pass with the guard never
    // exercised.
    private static (Task<T> a, Task<T> b, Action go) Paired<T>(Func<Task<T>> call)
    {
        var gate = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        async Task<T> Fire() { await gate.Task; return await call(); }
        return (Fire(), Fire(), () => gate.SetResult());
    }

    /// <summary>
    /// THE MESSAGE ARM: the retry applies, so the loser is answered by the ORDINARY RULE.
    ///
    /// On the retry the middleware re-fetches, the state now includes the winner's revision, and the
    /// decider's own <c>SubjectUnchanged</c> rule refuses it. One statement of the rule, not two.
    /// </summary>
    [Fact]
    public async Task the_message_arm_answers_a_lost_race_with_the_business_rule()
    {
        var emailId = Guid.NewGuid();
        await Given(emailId, new EmailDrafted(emailId, "someone@example.com", "Original", "body", SeedData.SeededAt));

        var bus = Host.Services.GetRequiredService<IMessageBus>();
        var (a, b, go) = Paired(() => bus.InvokeAsync<ReviseOutcome>(new ReviseSubject(emailId, "Revised")));
        go();
        var outcomes = await Task.WhenAll(a, b);

        output.WriteLine($"message arm -> {string.Join(" | ", outcomes.Select(o => o.Rule ?? "revised"))}");

        outcomes.Count(o => o.Rule is null).ShouldBe(1);
        outcomes.Count(o => o.Rule is not null).ShouldBe(1);
        (await EventsFor(emailId)).OfType<SubjectRevised>().Count().ShouldBe(1);
    }

    /// <summary>
    /// THE HTTP ARM: the retry does NOT apply, and the loser gets a 500.
    ///
    /// **This test asserts the DEFECT, deliberately.** It is the control that makes the test above mean
    /// something — without it, "the message arm refuses cleanly" cannot be told from "this race never
    /// reproduced". If a future Wolverine applies its retry policies to HTTP chains, THIS TEST GOES RED,
    /// which is exactly the signal wanted: come back and delete the two-file shape.
    /// </summary>
    [Fact]
    public async Task the_http_arm_loses_the_retry_and_a_lost_race_reaches_the_client_as_a_500()
    {
        var emailId = Guid.NewGuid();
        await Given(emailId, new EmailDrafted(emailId, "someone@example.com", "Original", "body", SeedData.SeededAt));

        var (a, b, go) = Paired(async () =>
        {
            var r = await Host.Scenario(x =>
            {
                x.Post.Json(new ReviseSubject(emailId, "Revised")).ToUrl($"/emails/{emailId}/subject");
                x.IgnoreStatusCode();
            });
            return r.Context.Response.StatusCode;
        });
        go();

        int[] codes;
        try { codes = await Task.WhenAll(a, b); }
        catch (Exception ex)
        {
            // Alba surfaces an unhandled endpoint exception by rethrowing rather than as a status code, which
            // is itself the finding: nothing between the decider and the caller turned it into a response.
            output.WriteLine($"http arm -> the collision escaped the endpoint: {ex.GetBaseException().GetType().Name}");
            ex.GetBaseException().GetType().Name.ShouldBe("EventStreamUnexpectedMaxEventIdException");
            (await EventsFor(emailId)).OfType<SubjectRevised>().Count().ShouldBe(1);
            return;
        }

        output.WriteLine($"http arm -> {string.Join(" | ", codes.OrderBy(c => c))}");
        codes.ShouldContain(c => c >= 500, "the lost race should have reached the client as a server error");
        (await EventsFor(emailId)).OfType<SubjectRevised>().Count().ShouldBe(1);
    }
}
